// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY, LogFile} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }

    function testFuzz_property(address actor, uint256 amount, uint256 lockTime) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 0, 1e30);
        lockTime = bound(lockTime, 0, 1e18);

        LogFile log = new LogFile();
        c.SetLogFile(address(log));

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(lockTime);

        bool ok;
        try log.History(0) returns (address sender, string memory, uint256, uint256) {
            ok = (sender == actor);
        } catch {
            ok = false;
        }
        assertTrue(ok, "After SetLogFile, any Put must be recorded in the configured LogFile with the depositor as sender");
    }
}
